from decimal import Decimal, InvalidOperation


def _text(value) -> str:
    return "" if value is None else str(value)


def _number(value) -> Decimal:
    text = _text(value)
    if text == "":
        return Decimal("0")
    try:
        return Decimal(text)
    except InvalidOperation:
        return Decimal("0")


def _field(record: dict, name: str) -> str:
    return _text(record.get(name, ""))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: str,
    out_col: str,
) -> str:
    if not tables:
        return ""

    for row in tables.get(table_name, []):
        if _text(row.get("DEL_FLG", "")) == "Y":
            continue
        if _text(row.get(key_col, "")) == key_val:
            return _text(row.get(out_col, ""))
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []
    old = old or {}

    def add(code: str, message: str) -> None:
        errors.append({"code": code, "message": message, "severity": "BLOCK"})

    if table == "ORD_HEADER":
        disc_pct = _number(_field(record, "DISC_PCT"))

        if event in ("INSERT", "UPDATE"):
            if not (disc_pct >= 0 and disc_pct <= 100):
                add("E5001", "Discount out of range")

        if event == "UPDATE":
            owner_uid = _field(record, "OWNER_UID")
            role_id = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            if disc_pct > 20 and role_id != "MGR" and role_id != "ADMIN":
                add(
                    "E5002",
                    "Discount over 20 percent requires manager role",
                )

            old_stat = _field(old, "STAT_CD")
            stat = _field(record, "STAT_CD")
            if old_stat == "I" and stat != "I" and stat != "X":
                add("E5003", "Invoiced order can only be cancelled")

    elif table == "ORD_LINE":
        if event in ("INSERT", "UPDATE"):
            if not (_number(_field(record, "QTY")) > 0):
                add("E5004", "Quantity must be positive")

        if event == "INSERT":
            prod_id = _field(record, "PROD_ID")
            active_flg = _lookup(
                tables, "PROD_MASTER", "PROD_ID", prod_id, "ACTIVE_FLG"
            )
            if active_flg != "Y":
                add("E5005", "Product not active")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
